mapper.select:
SELECT COUNT(*) FROM notifications
WHERE receiver_id = #{clientId}
  AND is_read = ${@com.uit.sociusmvcapp.notification.enums.NotificationStatus@UNREAD.code}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT id, receiver_id, delivery_type, payload_json, is_read, created_at, updated_at, deleted_at, delete_flag FROM notifications WHERE receiver_id = #{clientId} AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
AND ( created_at < #{lastCreatedAt} OR (created_at = #{lastCreatedAt} AND id < #{lastId}) )
ORDER BY created_at DESC, id DESC LIMIT #{limit}

